// Package orgclient is a thin wrapper over the org-svc gRPC TenantServiceClient.
// shell-bff uses it from WorkspacesHandler to fetch the user's accessible orgs
// and workspaces for the workspace-switcher popover.
//
// Transport credentials follow the same pattern as identityclient: mTLS when
// MTLS_*_FILE env vars are set, insecure otherwise.
package orgclient

import (
	"context"
	"time"

	"google.golang.org/grpc"
	"google.golang.org/grpc/metadata"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/grpcclient"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/mtls"
	feature_flagv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/feature_flag/v1"
	sharecodev1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/share_code/v1"
	tenantv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/tenant/v1"
)

// orgSvcCallTimeout bounds every org-svc gRPC call so a stalled org-svc cannot
// pin a shell-bff request goroutine.
const orgSvcCallTimeout = 5 * time.Second

// ContextWithDisplayName returns ctx with name appended as the
// auth.HeaderUserDisplayName gRPC metadata entry. Used on the
// ShareCodeService.CreateShareCode call so org-svc can snapshot the minting
// admin's display name into generated_by_display_name without a second
// identity lookup (org-visibility-code management surface, mirrors
// range-bff's orgclient.ContextWithDisplayName exactly). No-op when name is
// empty.
func ContextWithDisplayName(ctx context.Context, name string) context.Context {
	if name == "" {
		return ctx
	}
	return metadata.AppendToOutgoingContext(ctx, auth.HeaderUserDisplayName, name)
}

// Client wraps a gRPC connection to org-svc.
type Client struct {
	conn        *grpc.ClientConn
	tenant      tenantv1.TenantServiceClient
	featureFlag feature_flagv1.FeatureFlagServiceClient
	// shareCode is the org-svc ShareCodeService client, used by the
	// org-visibility-code MANAGEMENT surface (Create/List/Revoke) so a shell
	// org-settings page can mint/rotate/list/revoke the caller org's share
	// code directly.
	shareCode sharecodev1.ShareCodeServiceClient
	// userShareCode is the org-svc UserShareCodeService client, used by the
	// INDIVIDUAL (per-user) share-code surface (Create/Get/Revoke) so a user
	// can mint/rotate/revoke their own personal code from Account settings.
	userShareCode sharecodev1.UserShareCodeServiceClient
	// Mode reports whether the underlying transport is mTLS or insecure.
	Mode mtls.Mode
}

// NewClient dials org-svc at addr with the given mTLS posture.
func NewClient(addr string, mtlsCfg mtls.Config) (*Client, error) {
	creds, mode, err := mtls.BuildTransportCredentials(mtlsCfg)
	if err != nil {
		return nil, err
	}
	// P0-05: fail closed instead of silently dialing plaintext.
	if err := mtls.EnforceMode(mode); err != nil {
		return nil, err
	}
	// TierFast: org-svc calls from shell-bff are cheap intra-cluster lookups
	// already treated as ~5s de-facto (see orgSvcCallTimeout above, which most
	// call sites set explicitly); the interceptor only arms a fallback
	// deadline for the handful of calls (ListFeatureFlags, ListTenants,
	// GetTenantStudioFlags) that don't already set one.
	conn, err := grpc.NewClient(addr, grpcclient.DialOptions(grpcclient.TierFast, grpc.WithTransportCredentials(creds))...)
	if err != nil {
		return nil, err
	}
	return &Client{
		conn:          conn,
		tenant:        tenantv1.NewTenantServiceClient(conn),
		featureFlag:   feature_flagv1.NewFeatureFlagServiceClient(conn),
		shareCode:     sharecodev1.NewShareCodeServiceClient(conn),
		userShareCode: sharecodev1.NewUserShareCodeServiceClient(conn),
		Mode:          mode,
	}, nil
}

// ListFeatureFlags returns the effective enabled state for every known vertical
// key from org-svc. The feature-flag table is platform-global (no RLS), so
// no tenant GUC is required for this read-only call. The returned flags are
// keyed by vertical name ("dialogue", "range", "studio"); absent keys are
// default-on per org-svc semantics. The inbound ctx is forwarded as-is.
func (c *Client) ListFeatureFlags(ctx context.Context) (map[string]bool, error) {
	resp, err := c.featureFlag.ListFeatureFlags(ctx, &feature_flagv1.ListFeatureFlagsRequest{})
	if err != nil {
		return nil, err
	}
	flags := make(map[string]bool, len(resp.GetFlags()))
	for _, f := range resp.GetFlags() {
		flags[f.GetKey()] = f.GetEnabled()
	}
	return flags, nil
}

// Close releases the gRPC connection.
func (c *Client) Close() error {
	return c.conn.Close()
}

// ListMembershipsByUser returns every MembershipWithTenant row for the given
// identity-svc user_id. Satisfies handlers.OrgWorkspaceLister.
func (c *Client) ListMembershipsByUser(ctx context.Context, userID string) ([]*tenantv1.MembershipWithTenant, error) {
	resp, err := c.tenant.ListMembershipsByUser(ctx, &tenantv1.ListMembershipsByUserRequest{
		UserId: userID,
	})
	if err != nil {
		return nil, err
	}
	return resp.GetMemberships(), nil
}

// VerifyMembership resolves whether userID holds an active membership in orgID
// and, if so, the bare org role string ("OWNER"/"ADMIN"/"MEMBER"/"VIEWER"; ""
// for a non-member). Retained for the org-svc consumer pact contract; the
// shell-bff /session handler no longer calls it (org-svc gates this RPC to
// azp=keycloak-org-mapper, which rejects the user's browser bearer — the
// session resolves org_role via the self-read ListMembershipsByUser path
// instead). The inbound ctx is used as-is for outgoing metadata (same posture
// as ListMembershipsByUser) but bounded with a short deadline so a stalled
// org-svc cannot pin a request goroutine.
func (c *Client) VerifyMembership(ctx context.Context, userID, orgID string) (bool, string, error) {
	ctx, cancel := context.WithTimeout(ctx, orgSvcCallTimeout)
	defer cancel()

	resp, err := c.tenant.VerifyMembership(ctx, &tenantv1.VerifyMembershipRequest{
		UserId: userID,
		OrgId:  orgID,
	})
	if err != nil {
		return false, "", err
	}
	return resp.GetIsMember(), resp.GetMembershipRole(), nil
}

// ListTenants returns tenants whose parent_id matches parentID.
// Pass "" (empty string) to list root-level orgs (admin bypass path).
// Satisfies handlers.OrgWorkspaceLister.
//
// Wire-protocol note: org-svc's TenantService.List distinguishes three
// states by req.parent_id presence (optional string):
//
//   - nil pointer  → no filter, return ALL tenants
//   - "" string    → roots only (parent_id IS NULL)
//   - "<uuid>"     → children of that parent
//
// We MUST always set the pointer here, even for the empty case, so the
// admin bypass path actually scopes to roots. Leaving the pointer nil
// silently returns workspaces alongside roots and the workspace switcher
// surfaces each workspace twice (once as a child under its real parent
// and again as its own bogus "org" section).
func (c *Client) ListTenants(ctx context.Context, parentID string) ([]*tenantv1.Tenant, error) {
	resp, err := c.tenant.List(ctx, &tenantv1.ListRequest{
		ParentId: &parentID,
	})
	if err != nil {
		return nil, err
	}
	return resp.GetTenants(), nil
}

// GetTenantStudioFlags fetches the studio flags (disabled_studio_tools +
// offline_mode) for the given orgID. It calls TenantService.Get and returns
// only the two flag fields — the caller only needs those for the session
// endpoint. Returns (nil, false, err) on failure so the caller can decide
// whether to degrade gracefully.
func (c *Client) GetTenantStudioFlags(ctx context.Context, orgID string) ([]string, bool, error) {
	resp, err := c.tenant.Get(ctx, &tenantv1.GetRequest{TenantId: orgID})
	if err != nil {
		return nil, false, err
	}
	t := resp.GetTenant()
	if t == nil {
		return nil, false, nil
	}
	return t.GetDisabledStudioTools(), t.GetOfflineMode(), nil
}

// RecordWorkspaceSwitch records that userID moved from prevOrgID to newOrgID,
// forwarding the originating requestID for audit/trace correlation. The
// inbound ctx is used as-is for outgoing metadata (same posture as
// ListMembershipsByUser/ListTenants) but bounded with a short deadline so a
// stalled org-svc cannot pin a shell-bff request goroutine. The RPC response
// body is empty; success yields a nil error.
func (c *Client) RecordWorkspaceSwitch(ctx context.Context, userID, prevOrgID, newOrgID, requestID string) error {
	ctx, cancel := context.WithTimeout(ctx, orgSvcCallTimeout)
	defer cancel()

	_, err := c.tenant.RecordWorkspaceSwitch(ctx, &tenantv1.RecordWorkspaceSwitchRequest{
		UserId:    userID,
		PrevOrgId: prevOrgID,
		NewOrgId:  newOrgID,
		RequestId: requestID,
	})
	if err != nil {
		return err
	}
	return nil
}

// CreateShareCode mints or rotates the caller org's active share code via
// org-svc ShareCodeService (org-visibility-code management surface). The
// caller must pre-wire the bearer + x-tenant-id (forwarded by the handler's
// forwardAuthToOrgSvc) and, for display-name snapshotting, the caller's
// validated name (via ContextWithDisplayName) into ctx before calling — the
// org is derived server-side from x-tenant-id, never a request field.
// Returns the raw gRPC error on failure so the handler can translate it
// (org-svc is the authoritative OWNER/ADMIN gate: PermissionDenied → 403).
// Bounded with a short deadline so a stalled org-svc cannot pin the request
// goroutine.
func (c *Client) CreateShareCode(ctx context.Context, rotate bool) (*sharecodev1.ShareCode, error) {
	ctx, cancel := context.WithTimeout(ctx, orgSvcCallTimeout)
	defer cancel()

	resp, err := c.shareCode.CreateShareCode(ctx, &sharecodev1.CreateShareCodeRequest{Rotate: rotate})
	if err != nil {
		return nil, err
	}
	return resp.GetShareCode(), nil
}

// ListShareCodes returns the caller org's share codes (0 or 1 active, plus
// any revoked history) via org-svc ShareCodeService. The caller must
// pre-wire the bearer + x-tenant-id into ctx before calling.
func (c *Client) ListShareCodes(ctx context.Context) ([]*sharecodev1.ShareCode, error) {
	ctx, cancel := context.WithTimeout(ctx, orgSvcCallTimeout)
	defer cancel()

	resp, err := c.shareCode.ListShareCodes(ctx, &sharecodev1.ListShareCodesRequest{})
	if err != nil {
		return nil, err
	}
	return resp.GetShareCodes(), nil
}

// RevokeShareCode soft-revokes one of the caller org's share codes via
// org-svc ShareCodeService. Returns the post-image. The caller must
// pre-wire the bearer + x-tenant-id into ctx before calling.
func (c *Client) RevokeShareCode(ctx context.Context, id string) (*sharecodev1.ShareCode, error) {
	ctx, cancel := context.WithTimeout(ctx, orgSvcCallTimeout)
	defer cancel()

	resp, err := c.shareCode.RevokeShareCode(ctx, &sharecodev1.RevokeShareCodeRequest{Id: id})
	if err != nil {
		return nil, err
	}
	return resp.GetShareCode(), nil
}

// CreateUserShareCode mints or rotates the caller's active personal share
// code via org-svc UserShareCodeService (individual, per-user share-code
// surface). The caller must pre-wire the bearer + x-tenant-id + x-user-id
// (forwarded by the handler's forwardAuthToOrgSvc) into ctx before calling —
// the owning user is derived server-side from x-user-id, never a request
// field. Bounded with a short deadline so a stalled org-svc cannot pin the
// request goroutine.
func (c *Client) CreateUserShareCode(ctx context.Context, rotate bool) (*sharecodev1.UserShareCode, error) {
	ctx, cancel := context.WithTimeout(ctx, orgSvcCallTimeout)
	defer cancel()

	resp, err := c.userShareCode.CreateUserShareCode(ctx, &sharecodev1.CreateUserShareCodeRequest{Rotate: rotate})
	if err != nil {
		return nil, err
	}
	return resp.GetUserShareCode(), nil
}

// ListUserShareCodes returns all of the caller's active personal share codes
// via org-svc UserShareCodeService (multiple active codes per user are
// allowed, #332 follow-up). The caller must pre-wire the bearer +
// x-tenant-id + x-user-id into ctx before calling.
func (c *Client) ListUserShareCodes(ctx context.Context) ([]*sharecodev1.UserShareCode, error) {
	ctx, cancel := context.WithTimeout(ctx, orgSvcCallTimeout)
	defer cancel()

	resp, err := c.userShareCode.ListUserShareCodes(ctx, &sharecodev1.ListUserShareCodesRequest{})
	if err != nil {
		return nil, err
	}
	return resp.GetUserShareCodes(), nil
}

// RevokeUserShareCode soft-revokes the caller's personal share code via
// org-svc UserShareCodeService. Returns the post-image. The caller must
// pre-wire the bearer + x-tenant-id + x-user-id into ctx before calling.
func (c *Client) RevokeUserShareCode(ctx context.Context, id string) (*sharecodev1.UserShareCode, error) {
	ctx, cancel := context.WithTimeout(ctx, orgSvcCallTimeout)
	defer cancel()

	resp, err := c.userShareCode.RevokeUserShareCode(ctx, &sharecodev1.RevokeUserShareCodeRequest{Id: id})
	if err != nil {
		return nil, err
	}
	return resp.GetUserShareCode(), nil
}


