package orgclient

import (
	"context"
	"net"
	"testing"

	"github.com/stretchr/testify/require"
	"google.golang.org/grpc"
	"google.golang.org/grpc/credentials/insecure"
	"google.golang.org/grpc/test/bufconn"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/mtls"
	tenantv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/tenant/v1"
)

// fakeTenantServer is a bufconn-backed TenantServiceServer that records the
// last RecordWorkspaceSwitch request it received so the test can assert the
// orgclient.Client forwarded exactly the four fields.
type fakeTenantServer struct {
	tenantv1.UnimplementedTenantServiceServer

	gotRecordWorkspaceSwitch *tenantv1.RecordWorkspaceSwitchRequest
}

func (f *fakeTenantServer) RecordWorkspaceSwitch(_ context.Context, req *tenantv1.RecordWorkspaceSwitchRequest) (*tenantv1.RecordWorkspaceSwitchResponse, error) {
	f.gotRecordWorkspaceSwitch = req
	return &tenantv1.RecordWorkspaceSwitchResponse{}, nil
}

// newTestClient stands up an in-memory org-svc gRPC server backed by fake and
// returns an orgclient.Client wired to it over bufconn. Cleanup is registered
// on t.
func newTestClient(t *testing.T, fake tenantv1.TenantServiceServer) *Client {
	t.Helper()

	lis := bufconn.Listen(1024 * 1024)
	srv := grpc.NewServer()
	tenantv1.RegisterTenantServiceServer(srv, fake)

	go func() {
		_ = srv.Serve(lis)
	}()
	t.Cleanup(srv.Stop)

	conn, err := grpc.NewClient(
		"passthrough:///bufnet",
		grpc.WithContextDialer(func(ctx context.Context, _ string) (net.Conn, error) {
			return lis.DialContext(ctx)
		}),
		grpc.WithTransportCredentials(insecure.NewCredentials()),
	)
	require.NoError(t, err)
	t.Cleanup(func() { _ = conn.Close() })

	return &Client{
		conn:   conn,
		tenant: tenantv1.NewTenantServiceClient(conn),
		Mode:   mtls.ModeInsecure,
	}
}

func TestRecordWorkspaceSwitch_ForwardsFields(t *testing.T) {
	fake := &fakeTenantServer{}
	client := newTestClient(t, fake)

	const (
		userID    = "user-1"
		prevOrgID = "org-prev"
		newOrgID  = "org-new"
		requestID = "req-123"
	)

	err := client.RecordWorkspaceSwitch(context.Background(), userID, prevOrgID, newOrgID, requestID)
	require.NoError(t, err)

	got := fake.gotRecordWorkspaceSwitch
	require.NotNil(t, got, "RecordWorkspaceSwitch should have been invoked on the server")
	require.Equal(t, userID, got.GetUserId())
	require.Equal(t, prevOrgID, got.GetPrevOrgId())
	require.Equal(t, newOrgID, got.GetNewOrgId())
	require.Equal(t, requestID, got.GetRequestId())
}


