package orgclient

// Tests for the shell-bff orgclient ListFeatureFlags method.
// The method must call FeatureFlagService.ListFeatureFlags on the same
// grpc.ClientConn already used for TenantService calls.

import (
	"context"
	"net"
	"testing"

	"github.com/stretchr/testify/require"
	"google.golang.org/grpc"
	"google.golang.org/grpc/credentials/insecure"
	"google.golang.org/grpc/test/bufconn"

	feature_flagv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/feature_flag/v1"
	tenantv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/tenant/v1"
)

// fakeFeatureFlagServer is a stub FeatureFlagServiceServer that returns a
// canned list of flags so the test can confirm the orgclient routes the call
// to the right service and maps the response correctly.
type fakeFeatureFlagServer struct {
	feature_flagv1.UnimplementedFeatureFlagServiceServer
}

func (s *fakeFeatureFlagServer) ListFeatureFlags(
	_ context.Context, _ *feature_flagv1.ListFeatureFlagsRequest,
) (*feature_flagv1.ListFeatureFlagsResponse, error) {
	return &feature_flagv1.ListFeatureFlagsResponse{
		Flags: []*feature_flagv1.FeatureFlag{
			{Key: "dialogue", Enabled: true},
			{Key: "range", Enabled: false},
			{Key: "studio", Enabled: true},
		},
	}, nil
}

// newTestClientWithFeatureFlags builds a Client backed by an in-memory gRPC
// server that registers both TenantService and FeatureFlagService. The same
// *grpc.ClientConn routes both service calls, mirroring the production setup
// where both run in org-svc.
func newTestClientWithFeatureFlags(t *testing.T) *Client {
	t.Helper()

	fakeTenant := &fakeTenantServer{}
	fakeFF := &fakeFeatureFlagServer{}

	const bufSize = 1 << 20
	lis := bufconn.Listen(bufSize)
	srv := grpc.NewServer()
	tenantv1.RegisterTenantServiceServer(srv, fakeTenant)
	feature_flagv1.RegisterFeatureFlagServiceServer(srv, fakeFF)

	go func() { _ = srv.Serve(lis) }()
	t.Cleanup(func() {
		srv.GracefulStop()
		_ = lis.Close()
	})

	conn, err := grpc.NewClient(
		"passthrough:///bufnet",
		grpc.WithContextDialer(func(ctx context.Context, _ string) (net.Conn, error) {
			return lis.DialContext(ctx)
		}),
		grpc.WithTransportCredentials(insecure.NewCredentials()),
	)
	require.NoError(t, err)
	t.Cleanup(func() { _ = conn.Close() })

	return &Client{
		conn:        conn,
		tenant:      tenantv1.NewTenantServiceClient(conn),
		featureFlag: feature_flagv1.NewFeatureFlagServiceClient(conn),
	}
}

// TestListFeatureFlags_ReturnsMappedFlags asserts that ListFeatureFlags calls
// FeatureFlagService.ListFeatureFlags and returns the results as a map of
// vertical-key → enabled bool, preserving enabled/disabled state correctly.
func TestListFeatureFlags_ReturnsMappedFlags(t *testing.T) {
	client := newTestClientWithFeatureFlags(t)

	flags, err := client.ListFeatureFlags(context.Background())
	require.NoError(t, err)
	require.Len(t, flags, 3, "expected three flags from the server")

	require.True(t, flags["dialogue"], "dialogue should be enabled")
	require.False(t, flags["range"], "range should be disabled")
	require.True(t, flags["studio"], "studio should be enabled")
}

// emptyFeatureFlagServer returns an empty Flags slice (no rows in DB yet —
// all verticals are default-on at the cache level).
type emptyFeatureFlagServer struct {
	feature_flagv1.UnimplementedFeatureFlagServiceServer
}

func (s *emptyFeatureFlagServer) ListFeatureFlags(
	_ context.Context, _ *feature_flagv1.ListFeatureFlagsRequest,
) (*feature_flagv1.ListFeatureFlagsResponse, error) {
	return &feature_flagv1.ListFeatureFlagsResponse{}, nil
}

// TestListFeatureFlags_EmptyResponse covers the zero-flag case (fresh install
// where no rows exist yet — server returns an empty slice).
func TestListFeatureFlags_EmptyResponse(t *testing.T) {
	// Spin up a server that returns an empty flag list.
	const bufSize = 1 << 20
	lis := bufconn.Listen(bufSize)
	srv := grpc.NewServer()
	feature_flagv1.RegisterFeatureFlagServiceServer(srv, &emptyFeatureFlagServer{})
	go func() { _ = srv.Serve(lis) }()
	t.Cleanup(func() { srv.GracefulStop(); _ = lis.Close() })

	conn, err := grpc.NewClient(
		"passthrough:///bufnet",
		grpc.WithContextDialer(func(ctx context.Context, _ string) (net.Conn, error) {
			return lis.DialContext(ctx)
		}),
		grpc.WithTransportCredentials(insecure.NewCredentials()),
	)
	require.NoError(t, err)
	t.Cleanup(func() { _ = conn.Close() })

	client := &Client{
		conn:        conn,
		tenant:      tenantv1.NewTenantServiceClient(conn),
		featureFlag: feature_flagv1.NewFeatureFlagServiceClient(conn),
	}
	flags, err := client.ListFeatureFlags(context.Background())
	require.NoError(t, err)
	require.Empty(t, flags, "empty server response → empty map (featureflags.Cache treats absent keys as default-on)")
}



